import os
from dataclasses import dataclass
from typing import Optional


AUTH0_DOMAIN_ENV = "AUTH0_DOMAIN"
AUTH0_CLIENT_ID_ENV = "AUTH0_CLIENT_ID"
AUTH0_CLIENT_SECRET_ENV = "AUTH0_CLIENT_SECRET"
AUTH0_REDIRECT_URI_ENV = "AUTH0_REDIRECT_URI"
AUTH0_ISSUER_ENV = "AUTH0_ISSUER"
AUTH0_AUTHORIZE_PATH = "/authorize"
AUTH0_TOKEN_PATH = "/oauth/token"
AUTH0_USERINFO_PATH = "/userinfo"
AUTH0_SCOPE = "openid profile email"


@dataclass(frozen=True)
class IdentityClientConfig:
    domain: str
    client_id: str
    redirect_uri: str
    client_secret: Optional[str] = None
    issuer: Optional[str] = None
    scope: str = AUTH0_SCOPE

    @property
    def base_url(self) -> str:
        return f"https://{self.domain.rstrip('/')}"

    @property
    def authorize_url(self) -> str:
        return f"{self.base_url}{AUTH0_AUTHORIZE_PATH}"

    @property
    def token_url(self) -> str:
        return f"{self.base_url}{AUTH0_TOKEN_PATH}"

    @property
    def userinfo_url(self) -> str:
        return f"{self.base_url}{AUTH0_USERINFO_PATH}"

    @property
    def effective_issuer(self) -> str:
        return self.issuer or self.base_url


def _require_env(name: str) -> str:
    value = os.getenv(name)
    if not value:
        raise ValueError(f"{name} is required")
    return value


def load_identity_client_config() -> IdentityClientConfig:
    return IdentityClientConfig(
        domain=_require_env(AUTH0_DOMAIN_ENV),
        client_id=_require_env(AUTH0_CLIENT_ID_ENV),
        redirect_uri=_require_env(AUTH0_REDIRECT_URI_ENV),
        client_secret=os.getenv(AUTH0_CLIENT_SECRET_ENV),
        issuer=os.getenv(AUTH0_ISSUER_ENV),
    )


def build_authorization_params(
    config: IdentityClientConfig,
    state: str,
    nonce: str,
    code_challenge: str,
    code_challenge_method: str = "S256",
    audience: Optional[str] = None,
    organization: Optional[str] = None,
    connection: Optional[str] = None,
) -> dict:
    params = {
        "client_id": config.client_id,
        "redirect_uri": config.redirect_uri,
        "response_type": "code",
        "scope": config.scope,
        "state": state,
        "nonce": nonce,
        "code_challenge": code_challenge,
        "code_challenge_method": code_challenge_method,
    }
    if audience:
        params["audience"] = audience
    if organization:
        params["organization"] = organization
    if connection:
        params["connection"] = connection
    return params


def build_token_exchange_payload(
    config: IdentityClientConfig,
    code: str,
    code_verifier: str,
) -> dict:
    payload = {
        "grant_type": "authorization_code",
        "client_id": config.client_id,
        "code": code,
        "redirect_uri": config.redirect_uri,
        "code_verifier": code_verifier,
    }
    if config.client_secret:
        payload["client_secret"] = config.client_secret
    return payload


def build_userinfo_headers(access_token: str) -> dict:
    return {"Authorization": f"Bearer {access_token}", "Accept": "application/json"}


def resolve_identity_client_config(
    client_id: Optional[str] = None,
    redirect_uri: Optional[str] = None,
    domain: Optional[str] = None,
    client_secret: Optional[str] = None,
    issuer: Optional[str] = None,
) -> IdentityClientConfig:
    return IdentityClientConfig(
        domain=domain or _require_env(AUTH0_DOMAIN_ENV),
        client_id=client_id or _require_env(AUTH0_CLIENT_ID_ENV),
        redirect_uri=redirect_uri or _require_env(AUTH0_REDIRECT_URI_ENV),
        client_secret=client_secret if client_secret is not None else os.getenv(AUTH0_CLIENT_SECRET_ENV),
        issuer=issuer if issuer is not None else os.getenv(AUTH0_ISSUER_ENV),
    )

import base64
import hashlib
import json
import os
import secrets
import urllib.parse
import urllib.request
from dataclasses import dataclass
from typing import Dict, Optional

GOOGLE_AUTH_ENDPOINT = "https://accounts.google.com/o/oauth2/v2/auth"
GOOGLE_TOKEN_ENDPOINT = "https://oauth2.googleapis.com/token"
GOOGLE_USERINFO_ENDPOINT = "https://openidconnect.googleapis.com/v1/userinfo"

@dataclass(frozen=True)
class PKCELoginConfig:
    client_id: str
    redirect_uri: str
    scope: str = "openid email profile"
    auth_endpoint: str = GOOGLE_AUTH_ENDPOINT
    token_endpoint: str = GOOGLE_TOKEN_ENDPOINT
    userinfo_endpoint: str = GOOGLE_USERINFO_ENDPOINT


def _base64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def generate_code_verifier(length: int = 64) -> str:
    if not 43 <= length <= 128:
        raise ValueError("PKCE verifier length must be between 43 and 128")
    return _base64url(secrets.token_bytes(length))[:length]


def generate_code_challenge(verifier: str) -> str:
    digest = hashlib.sha256(verifier.encode("ascii")).digest()
    return _base64url(digest)


def build_authorization_url(config: PKCELoginConfig, state: Optional[str] = None, code_verifier: Optional[str] = None) -> Dict[str, str]:
    verifier = code_verifier or generate_code_verifier()
    challenge = generate_code_challenge(verifier)
    params = {
        "client_id": config.client_id,
        "redirect_uri": config.redirect_uri,
        "response_type": "code",
        "scope": config.scope,
        "code_challenge": challenge,
        "code_challenge_method": "S256",
    }
    if state is None:
        state = _base64url(secrets.token_bytes(16))
    params["state"] = state
    return {"authorization_url": f"{config.auth_endpoint}?{urllib.parse.urlencode(params)}", "state": state, "code_verifier": verifier}


def exchange_code_for_tokens(config: PKCELoginConfig, code: str, code_verifier: str) -> Dict[str, object]:
    payload = urllib.parse.urlencode({
        "client_id": config.client_id,
        "grant_type": "authorization_code",
        "code": code,
        "redirect_uri": config.redirect_uri,
        "code_verifier": code_verifier,
    }).encode("utf-8")
    request = urllib.request.Request(config.token_endpoint, data=payload, headers={"Content-Type": "application/x-www-form-urlencoded"})
    with urllib.request.urlopen(request, timeout=30) as response:
        return json.loads(response.read().decode("utf-8"))


def fetch_userinfo(config: PKCELoginConfig, access_token: str) -> Dict[str, object]:
    request = urllib.request.Request(config.userinfo_endpoint, headers={"Authorization": f"Bearer {access_token}"})
    with urllib.request.urlopen(request, timeout=30) as response:
        return json.loads(response.read().decode("utf-8"))


def pkce_login_flow(client_id: Optional[str] = None, redirect_uri: Optional[str] = None, code: Optional[str] = None, state: Optional[str] = None, code_verifier: Optional[str] = None) -> Dict[str, object]:
    client_id = client_id or os.environ["GOOGLE_OAUTH_CLIENT_ID"]
    redirect_uri = redirect_uri or os.environ["GOOGLE_OAUTH_REDIRECT_URI"]
    config = PKCELoginConfig(client_id=client_id, redirect_uri=redirect_uri)
    if code is None:
        return build_authorization_url(config, state=state, code_verifier=code_verifier)
    if code_verifier is None:
        raise ValueError("code_verifier is required to exchange the authorization code")
    tokens = exchange_code_for_tokens(config, code, code_verifier)
    result = {"tokens": tokens}
    access_token = tokens.get("access_token")
    if isinstance(access_token, str) and access_token:
        result["userinfo"] = fetch_userinfo(config, access_token)
    return result

from dataclasses import dataclass
from typing import Any, Dict, Optional

import requests


MICROSOFT_GRAPH_ME_ENDPOINT = "https://graph.microsoft.com/v1.0/me"


@dataclass
class ProfileClaims:
    subject: str
    email: Optional[str]
    given_name: Optional[str]
    family_name: Optional[str]
    display_name: Optional[str]
    locale: Optional[str]
    raw: Dict[str, Any]


def _pick_email(payload: Dict[str, Any]) -> Optional[str]:
    for key in ("mail", "userPrincipalName", "preferred_username", "email"):
        value = payload.get(key)
        if isinstance(value, str) and value:
            return value
    return None


def _pick_subject(payload: Dict[str, Any]) -> str:
    for key in ("id", "sub", "oid"):
        value = payload.get(key)
        if isinstance(value, str) and value:
            return value
    email = _pick_email(payload)
    if email:
        return email
    raise ValueError("Unable to determine subject from Microsoft Graph profile")


def normalize_profile_claims(payload: Dict[str, Any]) -> ProfileClaims:
    return ProfileClaims(
        subject=_pick_subject(payload),
        email=_pick_email(payload),
        given_name=payload.get("givenName") if isinstance(payload.get("givenName"), str) else None,
        family_name=payload.get("surname") if isinstance(payload.get("surname"), str) else None,
        display_name=payload.get("displayName") if isinstance(payload.get("displayName"), str) else None,
        locale=payload.get("preferredLanguage") if isinstance(payload.get("preferredLanguage"), str) else None,
        raw=payload,
    )


def fetch_profile_claims(access_token: str, session: Optional[requests.Session] = None) -> ProfileClaims:
    client = session or requests.Session()
    response = client.get(
        MICROSOFT_GRAPH_ME_ENDPOINT,
        headers={"Authorization": f"Bearer {access_token}", "Accept": "application/json"},
        timeout=30,
    )
    response.raise_for_status()
    payload = response.json()
    if not isinstance(payload, dict):
        raise ValueError("Microsoft Graph profile response must be an object")
    return normalize_profile_claims(payload)

